import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Cooking","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/cooking.md","filePath":"en/guide/professions/cooking.md"}'),r={name:"en/guide/professions/cooking.md"};function s(n,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="cooking" tabindex="-1">Cooking <a class="header-anchor" href="#cooking" aria-label="Permalink to &quot;Cooking&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Cook at a real station, choosing when to prepare and combine ingredients.</li><li>Food should support survival, comfort and recovery.</li><li>Recipes, cultures and personal tastes give cooks reasons to explore.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Set up</td><td>Use a campfire cooking stand, kitchen, stove, oven or grill.</td></tr><tr><td>Prepare</td><td>Ingredients start cooking when placed in the work area; watch their different preparation windows.</td></tr><tr><td>Discover</td><td>Build a Culinary Journal through cooks, books, cultures and experiments; discover preferences through eating.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Ingredients, tools and suitable heat produce listed dishes.</td><td>Timing and assembly become interactive choices at the station.</td></tr><tr><td>UO includes hunger and food; later eras also add special food effects.</td><td>Emphasis falls on nutrition, recovery and comfort rather than generic stat buffs.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/cooking/" target="_blank" rel="noreferrer">Cooking</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>At camp, a cook could prepare ingredients at different times and assemble a favorite dish for a companion. Its exact comfort and recovery benefits remain undecided.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Low <a href="/Syrolands-Public/en/guide/characters/skills.html">skill</a> should already produce useful simple meals. Higher skill widens tolerances without replacing execution.</li><li>Fuel connects Cooking with Camping and Lumberjacking. Nutrition, temperature, <a href="/Syrolands-Public/en/guide/glossary.html#fatigue">fatigue</a> and taste effects remain open.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/cooking.html">Cooking</a></p>',18)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
